from pathlib import Path
p=Path('work/pocket-research/compile.cjs');s=p.read_text(encoding='utf-8');i=s.index(' // Independent printed clauses')
s=s[:i]+r'''
 if((m=text.match(/^1 of your opponent's (Benched )?Pokémon is chosen at random(?: (\d+) times)?\. (?:For each time a Pokémon was chosen, (also )?do|Do) (\d+) damage to it\.$/)))return[...(m[3]?[hit]:[]),{kind:'randomHits',bench:!!m[1],count:+m[2]||1,amount:+m[4]}];
 if((m=text.match(/^1 of your opponent's Benched Pokémon is chosen at random\. This attack also does (\d+) damage to it\.$/)))return[hit,{kind:'randomHits',bench:true,count:1,amount:+m[1]}];
 if((m=text.match(/^1 of your opponent's Pokémon is chosen at random for each \[([A-Z])\] Energy attached to this Pokémon\. For each time a Pokémon was chosen, do (\d+) damage to it\.$/)))return[{kind:'randomHits',energyCount:true,type:m[1],amount:+m[2]}];
 if((m=text.match(/^1 other Pokémon \(either yours or your opponent's\) is chosen at random (\d+) times?\. (?:For each time a Pokémon was chosen, do (\d+) damage to it|Do (\d+) damage to the chosen Pokémon)\.$/)))return[{kind:'randomHits',both:true,notSelf:true,count:+m[1],amount:+m[2]||+m[3]}];
 if((m=text.match(/^This attack is used twice in a row\. The second attack does (\d+) damage\./)))return[hit,{kind:'checkKO'},{kind:'secondAttack',amount:+m[1]}];
 if((m=text.match(/^Discard all \[([A-Z])\] and \[([A-Z])\] Energy from this Pokémon, and this attack does (\d+) damage for each Energy you discarded in this way\.$/)))return[{kind:'discardScaledDamage',types:m.slice(1,3),amount:+m[3]}];
 if((m=text.match(/^This attack's damage is reduced by the amount of damage this Pokémon has on it\.$/)))return[{kind:'scaledDamage',base:+damage||0,amount:-10,scale:'ownDamage'}];
 if((m=text.match(/^This attack does (\d+) more damage for each of your opponent's Pokémon in play that has an Ability\.$/)))return[{kind:'scaledDamage',base:+damage||0,amount:+m[1],scale:'opponentAbilities'}];
 if((m=text.match(/^This attack does (\d+) more damage for each Trainer card in your opponent's deck\.$/)))return[{kind:'scaledDamage',base:+damage||0,amount:+m[1],scale:'opponentDeckTrainers'}];
 if((m=text.match(/^This attack does (\d+) more damage for each point your opponent got during their last turn\.$/)))return[{kind:'scaledDamage',base:+damage||0,amount:+m[1],scale:'opponentLastPoints'}];
 if((m=text.match(/^If your opponent has gotten exactly (\d+) point, this attack does (\d+) more damage\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[2],predicate:{test:'opponentPoints',min:+m[1],max:+m[1]}}];
 if((m=text.match(/^If you have fewer Pokémon in play than your opponent, this attack does (\d+) more damage\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[1],predicate:{test:'fewerPokemon'}}];
 if((m=text.match(/^If this Pokémon and your opponent's Active Pokémon have the same amount of Energy attached, this attack does (\d+) more damage\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[1],predicate:{test:'equalEnergy'}}];
 if(text==="If this Pokémon didn't move from the Bench to the Active Spot this turn, this attack does nothing.")return[{kind:'when',predicate:{test:'promoted'},then:[hit]}];
 if(text==="If this Pokémon has damage on it, this attack does -100 damage.")return[{kind:'conditionalDamage',base:+damage||0,amount:-100,predicate:{test:'woundedSelf'}}];
 if((m=text.match(/^If this Pokémon has any \[([A-Z])\] Energy attached, this attack does (\d+) more damage\. This attack's damage isn't affected by any effects on your opponent's Active Pokémon\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[2],condition:'hasEnergy',type:m[1],ignore:true}];
 if(text==="This attack's damage isn't affected by any effects on your opponent's Active Pokémon.")return[{...hit,ignore:true}];
 if((m=text.match(/^Flip a coin\. If heads, take (\d+) \[([A-Z])\] Energy from your Energy Zone and attach it to (this Pokémon|1 of your Benched Pokémon)\.$/)))return[hit,{kind:'condition',then:m[3]==='this Pokémon'?[{kind:'zoneEnergy',amount:+m[1],type:m[2]}]:[{kind:'choosePokemon',bench:true,optional:true,next:[{kind:'zoneEnergy',amount:+m[1],type:m[2]}]}]}];
 if((m=text.match(/^Take a \[([A-Z])\] and a \[([A-Z])\] Energy from your Energy Zone and attach them to this Pokémon\.$/)))return[hit,...m.slice(1).map(type=>({kind:'zoneEnergy',type,amount:1}))];
 if((m=text.match(/^Discard a \[([A-Z])\] and a \[([A-Z])\] Energy from this Pokémon\.$/)))return[hit,...m.slice(1).map(type=>({kind:'discardEnergy',type,amount:1}))];
 if((m=text.match(/^This Pokémon also does (\d+) damage to itself and (\d+) damage to all Benched Pokémon \(both yours and your opponent's\)\.$/)))return[hit,{kind:'recoil',amount:+m[1]},{kind:'benchDamage',amount:+m[2]},{kind:'benchDamage',amount:+m[2],self:true}];
 if(text==='This Pokémon is now Asleep. Heal 30 damage from it.')return[hit,{kind:'status',self:true,status:'Asleep'},{kind:'heal',amount:30}];
 if(text==='Heal from this Pokémon the same amount of damage you did to your opponent\'s Active Pokémon.')return[hit,{kind:'healDamageDone'}];
 if((m=text.match(/^Heal (\d+) damage from 1 of your Pokémon\.$/)))return[hit,{kind:'choosePokemon',wounded:true,optional:true,next:[{kind:'heal',amount:+m[1]}]}];
 if(text==='During your opponent\'s next turn, this Pokémon has no Weakness.')return[hit,{kind:'lock',effect:'noWeakness'}];
 if(text==='During your next turn, the Defending Pokémon takes +50 damage from attacks.')return[hit,{kind:'lock',opponent:true,nextOwn:true,effect:'vulnerable',amount:50}];
 if((m=text.match(/^During your opponent's next turn, attacks used by the Defending Pokémon cost (\d+) \[C\] more, and its Retreat Cost is (\d+) \[C\] more\.$/)))return[hit,{kind:'lock',opponent:true,effect:'extraCost',amount:+m[1]},{kind:'lock',opponent:true,effect:'retreatMore',amount:+m[2]}];
 if(text==="During your opponent's next turn, they can't play any Pokémon from their hand to evolve their Pokémon.")return[hit,{kind:'playerLock',effect:'evolution'}];
 if(text==='Your opponent\'s Active Pokémon is now Poisoned. During your opponent\'s next turn, that Pokémon can\'t retreat.')return[hit,{kind:'status',status:'Poisoned'},{kind:'lock',opponent:true,effect:'cantRetreat'}];
 if((m=text.match(/^Your opponent's Active Pokémon is now Poisoned\. Do (\d+) damage to this Pokémon instead of the usual amount for this Special Condition\.$/)))return[hit,{kind:'status',status:'Poisoned',poisonDamage:+m[1]}];
 if(text==='Halve your opponent\'s Active Pokémon\'s remaining HP, rounded down.')return[{kind:'setRemainingHp',half:true}];
 if(text==="Flip a coin. If heads, your opponent's Active Pokémon's remaining HP is now 10.")return[hit,{kind:'condition',then:[{kind:'setRemainingHp',hp:10}]}];
 if(text==="Flip a coin. If heads, during your opponent's next turn, prevent all damage done to this Pokémon by attacks.")return[hit,{kind:'condition',then:[{kind:'lock',effect:'preventDamage'}]}];
 if(text==='Prevent all damage done to this Pokémon by attacks from Basic Pokémon during your opponent\'s next turn.')return[hit,{kind:'lock',effect:'preventBasicDamage'}];
 if(text==='During your opponent\'s next turn, prevent all damage done to this Pokémon by attacks if that damage is 40 or less.')return[hit,{kind:'lock',effect:'preventSmallDamage',amount:40}];
 if(text==='Discard all Pokémon Tools from your opponent\'s Active Pokémon.')return[hit,{kind:'discardTool',opponent:true}];
 if(text==='Discard a Stadium in play.')return[hit,{kind:'removeStadium'}];
 if(text==='Discard the top 5 cards of each player\'s deck.')return[hit,{kind:'mill',amount:5},{kind:'mill',amount:5,opponent:true}];
 if(text==='Draw cards until you have the same number of cards in your hand as your opponent.')return[hit,{kind:'drawToOpponent'}];
 if(text==='Draw a card for each Poochyena you have in play.')return[hit,{kind:'drawScaled',names:['Poochyena']}];
 if(text==='Before doing damage, shuffle all Pokémon Tools from each of your opponent\'s Pokémon into their deck.')return[{kind:'allTools',opponent:true,toDeck:true},hit];
 if((m=text.match(/^Put (\d+) random cards from among (.+) from your deck onto your Bench\.$/)))return Array.from({length:+m[1]},()=>({kind:'benchRandom',names:m[2].split(' and '),allowEvolution:true}));
 if((m=text.match(/^Flip a coin for each (.+) you have in play\. This attack does (\d+) damage for each heads\.$/)))return[{kind:'coinDamage',pokemonCount:true,names:m[1].split(' and '),base:0,amount:+m[2]}];
 if(text==='Flip 2 coins. This attack does 30 damage for each heads. If this Pokémon has Lucky Mittens attached, flip 4 coins instead.')return[{kind:'coinDamage',count:2,toolCount:{name:'Lucky Mittens',count:4},base:0,amount:30}];
 if(text==='Flip a coin. If heads, your opponent\'s Active Pokémon is now Confused. If tails, this Pokémon is now Confused.')return[hit,{kind:'condition',then:[{kind:'status',status:'Confused'}],else:[{kind:'status',status:'Confused',self:true}]}];
 if(text==='Flip 3 coins. For each heads, discard a random Energy from your opponent\'s Active Pokémon.')return[hit,{kind:'countCoins',count:3,then:{kind:'coinEnergyDiscard',opponent:true}}];
 if(text==='Flip a coin until you get tails. For each heads, discard the top card of your opponent\'s deck.')return[hit,{kind:'untilTailsMill'}];
 if(text==='Flip 3 coins. If 1 of them is heads, this attack does 20 more damage. If 2 of them are heads, this attack does 50 more damage. If all of them are heads, this attack does 120 more damage.')return[{kind:'countCoins',count:3,then:{kind:'coinBonusTable',base:+damage||0,table:[0,20,50,120]}}];
 if(text==='Flip a coin. If heads, this attack does 70 damage to your opponent\'s Active Pokémon. If tails, heal 30 damage from your opponent\'s Active Pokémon.')return[{kind:'condition',then:[{kind:'damage',amount:70}],else:[{kind:'healOpponent',amount:30}]}];
 if(text==='Discard Fire[R] Energy from this Pokémon. Your opponent\'s Active Pokémon is now Burned.')return[hit,{kind:'discardEnergy',amount:1,type:'R'},{kind:'status',status:'Burned'}];
''' +s[i:];p.write_text(s,encoding='utf-8')
